const {test}=require('node:test'),assert=require('node:assert/strict'),C=require('../src/core.js'),T=require('../src/passive-catalog.js'),M=require('../src/passive-model.js'),E=C.EFFECTS;
const seed=()=>{const p=C.fresh();p.level=99;p.gold=100;p.x=715;p.y=1610;return p;};
const stats=(mods={},setup=()=>{})=>{const p=seed();setup(p);return E.derive(p,mods,C.ITEMS);};
const double=p=>{p.equipment.weapon='espadao_treino';p.equipment.offhand='espadao_treino';};
const dual=p=>{p.equipment.weapon='lamina';p.equipment.offhand='espada';};
const profile=(kind='physical',source='melee',area=false)=>({kind,source,area});
const attack=(s,p=profile())=>E.attackPower(s,p);
const dot=(s,kind)=>E.attack(s,profile(),{evasion:0},()=>0).dots.find(d=>d.kind===kind);
const coverage={
 strength:s=>s.forca,dexterity:s=>s.destreza,magic:s=>s.magia,vitality:s=>s.vitalidade,
 physical:s=>attack(s),melee:s=>attack(s),oneHand:s=>attack(s),twoHand:{setup:double,get:s=>attack(s)},dual:{setup:dual,get:s=>attack(s)},area:s=>attack(s,profile('physical','melee',true)),penetration:s=>E.attack(s,{...profile(),basePower:100},{defense:500,evasion:0},()=>.5).damage,
 maxLife:s=>s.hp,lifeRegen:s=>E.regen(s,false).hp,lifeFlat:s=>s.hp,lifeRecovery:s=>E.potion(s,'hp'),hpPotion:s=>E.potion(s,'hp'),
 maxMana:s=>s.mp,manaRegen:s=>E.regen(s,false).mp,manaFlat:s=>s.mp,magicDamage:s=>attack(s,profile('magic','spell')),manaCost:s=>10*s.manaCostMultiplier,magicDefense:s=>E.incoming(s,100,'magic'),
 elemental:s=>attack(s,profile('fire','spell')),fire:s=>attack(s,profile('fire','spell')),cold:s=>attack(s,profile('cold','spell')),lightning:s=>attack(s,profile('lightning','spell')),fireResist:s=>E.incoming(s,100,'fire'),coldResist:s=>E.incoming(s,100,'cold'),lightningResist:s=>E.incoming(s,100,'lightning'),
 attackSpeed:s=>.58/s.attackSpeed,accuracy:s=>E.hitChance(s,{evasion:25},profile()),critChance:s=>s.crit,critDamage:s=>E.attack(s,profile(),{evasion:0},()=>0).damage,projectile:s=>attack(s,profile('physical','projectile')),
 poisonChance:s=>s.poisonChance,poisonDamage:s=>dot(s,'poison').power,poisonDuration:s=>dot(s,'poison').duration,bleedChance:s=>s.bleedChance,bleedDamage:s=>dot(s,'bleed').power,damageOverTime:s=>dot(s,'bleed').power,poisonResist:s=>E.incoming(s,100,'poison'),directDamage:s=>attack(s),
 physicalDefense:s=>E.incoming(s,100,'physical'),blockChance:s=>s.blockChance,blockRecovery:s=>s.blockRecovery,stunResist:s=>E.stunDuration(s,1),shieldDefense:s=>s.defense,
 moveSpeed:s=>s.moveSpeed,slowResist:s=>E.slowAmount(s,.4),mpPotion:s=>E.potion(s,'mp'),resourceRecovery:s=>E.potion(s,'mp')
};
for(const key of Object.keys(T.MODS))test('modificador '+key+' modifica seu cálculo efetivo',()=>{const spec=coverage[key];assert.ok(spec,'modificador sem consumidor');const get=typeof spec==='function'?spec:spec.get,setup=spec.setup||(()=>{}),baseline={poisonChance:key==='poisonChance'?0:100,bleedChance:key==='bleedChance'?0:100},before=stats(baseline,setup),after=stats({...baseline,[key]:10},setup);assert.notEqual(get(after),get(before),key+' sem efeito');});
test('todo modificador do catálogo possui consumidor coberto',()=>assert.deepEqual(Object.keys(coverage).sort(),Object.keys(T.MODS).sort()));
test('grafo único permite todas as 800 passivas e todas têm bônus conhecidos',()=>{assert.equal(T.nodes.length,801);assert.ok(M.connected(T.nodes.map(n=>n.id)));for(const n of T.nodes.filter(n=>n.id!=='root')){assert.ok(n.title);for(const k of Object.keys(n.mods))assert.ok(T.MODS[k]);}});
test('aplicar caminho confirma orçamento e stats sem acumular bônus nem curar',()=>{const p=seed(),path=M.pathTo(new Set(),'cluster_0_0_notable');p.hp=200;const before=C.stats(p);assert.ok(C.commitPassives(p,path));assert.ok(C.stats(p).forca>before.forca);assert.ok(C.stats(p).power>before.power);assert.equal(p.treePoints,98-path.length);assert.equal(p.hp,200);const current=C.stats(p).power;for(let i=0;i<5;i++)assert.equal(C.stats(p).power,current);assert.equal(C.commitPassives(p,path),false);const restored=C.validateSave(JSON.parse(JSON.stringify(p)));assert.deepEqual(restored.tree,p.tree);assert.equal(C.stats(restored).power,current);});
test('limites e conexão invalidam toda a operação antes de mudar stats',()=>{const p=C.fresh(),before=JSON.stringify(p);assert.equal(C.commitPassives(p,['road_0_1']),false);assert.equal(C.commitPassives(p,['keystone_0']),false);assert.equal(JSON.stringify(p),before);p.level=99;assert.equal(C.commitPassives(p,['road_0_1','road_0_1']),false);assert.equal(C.commitPassives(p,['fake']),false);});
test('respec cobra uma vez, exige clareira e retorna equipamento sem requisitos à mochila',()=>{const p=seed(),path=M.pathTo(new Set(),'road_0_5');assert.ok(C.commitPassives(p,path));p.bag.push('lamina');assert.ok(C.equip(p,'lamina'));p.x=1200;const before=JSON.stringify(p);assert.equal(C.commitPassives(p,[],{combat:0}),false);assert.equal(JSON.stringify(p),before);p.x=715;p.y=1610;assert.equal(C.commitPassives(p,[],{combat:2}),false);assert.ok(C.commitPassives(p,[],{combat:0}));assert.equal(p.gold,80);assert.equal(p.equipment.weapon,'espada');assert.equal(p.bag.filter(id=>id==='lamina').length,1);assert.equal(p.treePoints,98);assert.equal(C.commitPassives(p,[],{combat:0}),false);assert.equal(p.gold,80);});
test('bônus condicionais não afetam arma errada, fonte errada ou personagem sem escudo',()=>{const one=stats({twoHand:30}),plain=stats();assert.equal(one.power,plain.power);assert.equal(attack(stats({projectile:30})),attack(plain));assert.equal(attack(stats({fire:30}),profile('cold','spell')),attack(plain,profile('cold','spell')));assert.equal(attack(stats({magicDamage:30})),attack(plain));const noShield=stats({blockChance:50,shieldDefense:50},p=>{p.equipment.offhand=null;p.equipment.shield=null;});assert.equal(noShield.blockChance,0);assert.equal(noShield.defense,60);});
test('precisão, crítico, penetração e área entram no resultado do acerto',()=>{const s=stats({accuracy:25,critDamage:25,penetration:25,area:20});assert.equal(E.attack(s,profile(),{evasion:100},()=>1).hit,false);const target={evasion:0,defense:200};assert.ok(E.attack(s,profile(),target,()=>0).damage>E.attack(stats(),profile(),target,()=>0).damage);assert.ok(E.attack(s,profile('physical','melee',true),target,()=>.5).damage>E.attack(s,profile(),target,()=>.5).damage);});
test('dano contínuo não é reduzido pela penalidade de dano direto',()=>{const s=stats({poisonChance:100,bleedChance:100,damageOverTime:35,directDamage:-12}),plain=stats({poisonChance:100,bleedChance:100});assert.ok(attack(s)<attack(plain));assert.ok(dot(s,'poison').power>dot(plain,'poison').power);assert.ok(dot(s,'bleed').power>dot(plain,'bleed').power);});
test('máximos de resistência e velocidade e custo mínimo evitam inversões de valores',()=>{const s=stats({fireResist:999,critChance:999,attackSpeed:999,moveSpeed:999,manaCost:999});assert.equal(s.resists.fire,.75);assert.equal(s.crit,.75);assert.equal(s.attackSpeed,2);assert.equal(s.moveSpeed,198);assert.ok(Math.abs(s.manaCostMultiplier-.2)<1e-8);assert.ok(E.incoming(s,100,'fire')>0);});
test('saves antigos devolvem os pontos e mantêm nível, atributos e itens',()=>{const old=seed();delete old.passiveVersion;old.tree=['f1','v1','bastiao'];old.attrs.forca=15;old.bag.push('lamina');old.equipment.weapon='lamina';const migrated=C.validateSave(old);assert.equal(migrated.passiveVersion,2);assert.deepEqual(migrated.tree,[]);assert.equal(migrated.treePoints,98);assert.equal(migrated.passiveRefunded,3);assert.equal(migrated.attrs.forca,15);assert.equal(migrated.equipment.weapon,'lamina');});

test('estudo separado não pode ser importado como jornada do personagem',()=>assert.throws(()=>C.validateSave({version:1,level:25,nodes:['road_0_1']}),/estudo da árvore/));
